def rectangles_overlap(r1, r2):
    def x_overlap(a, b):
        return a[2] > b[1] and b[2] > a[1]
    def y_overlap(a, b):
        return a[3] > b[2] and b[3] > a[2]
    def interiors_overlap(a, b):
        a_has_feet = a[1] == 0 and a[2] == 0 and a[3] == 0
        a_has_left_cheek = a[2] == 1 and a[3] == 1
        b_has_feet = b[1] == 0 and b[2] == 0 and b[3] == 0
        b_has_left_cheek = b[2] == 1 and b[3] == 1
        a_low = a_has_feet or a_has_left_cheek
        b_low = b_has_feet or b_has_left_cheek
        if a_low and b_low:
            return r1 == (0, 0, 0, 0) and r2 == (1, 1, 2, 1)
        if a_low and not b_low:
            return r2 == (0, 0, 0, 0)
        if b_low and not a_low:
            return r1 == (0, 0, 0, 0)
        return x_overlap(r1, r2) and y_overlap(r1, r2)
    return interiors_overlap(r1, r2)
